steps.action:
curl -s -X POST https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: <TOKEN>" -d '{"query":"{ __schema { types { name inputFields { name } args { name } } fields { name args { name } } } }"}' | python3 -c "
import sys,json
d=json.load(sys.stdin)
for t in d['data']['__schema']['types']:
    for f in (t.get('inputFields') or []):
        if f['name'].lower()=='app': print('INPUTFIELD',t['name'],':',f['name'])
    for f in (t.get('fields') or []):
        for a in (f.get('args') or []):
            if a['name'].lower()=='app': print('ARG',t['name']+'.'+f['name'],':',a['name'])
"
